<template><div><el-page-header @back="$router.push('/admin/batches')" title="返回"/><div class="stats"><div v-for="item in statCards" :key="item.key" class="stat" :class="{clickable:item.key==='unsubmitted'}" @click="item.key==='unsubmitted'&&openUnsubmitted()"><span>{{item.label}}</span><strong>{{item.value}}</strong></div></div><el-progress :percentage="Number(progress.completionRate||0)" :stroke-width="12"/><el-card class="college-card"><template #header>各学院参与进度</template><el-table :data="progress.colleges||[]" size="small"><el-table-column prop="college" label="学院"/><el-table-column prop="total" label="应填" width="80"/><el-table-column prop="participated" label="已参与" width="80"/><el-table-column label="完成率"><template #default="{row}"><el-progress :percentage="Number(row.rate)"/></template></el-table-column></el-table></el-card><div class="toolbar"><el-select v-model="filterStatus" placeholder="筛选状态" clearable @change="loadSubmissions"><el-option label="全部" value=""/><el-option label="草稿" value="DRAFT"/><el-option label="已提交" value="SUBMITTED"/><el-option label="已通过" value="APPROVED"/><el-option label="已驳回" value="REJECTED"/></el-select><el-button type="success" @click="exportExcel">导出填报</el-button></div><el-table :data="submissions" @selection-change="rows=>selectedIds=rows.map(r=>r.id)" v-loading="loading"><el-table-column type="selection" width="48"/><el-table-column prop="counselorName" label="辅导员"/><el-table-column prop="collegeName" label="学院"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="statusTag(row.status)">{{statusLabel(row.status)}}</el-tag></template></el-table-column><el-table-column label="操作" width="220"><template #default="{row}"><el-button size="small" @click="viewDetail(row)">详情</el-button><el-button v-if="row.status==='SUBMITTED'" size="small" type="success" @click="approve(row.id)">通过</el-button><el-button v-if="row.status==='SUBMITTED'" size="small" type="danger" @click="reject(row.id)">驳回</el-button></template></el-table-column></el-table><el-button v-if="selectedIds.length" type="success" style="margin-top:12px" @click="batchApprove">批量通过</el-button>
<el-dialog v-model="detailVisible" title="填报详情" width="min(94%,720px)"><el-descriptions :column="isMobile?1:2" border><el-descriptions-item label="姓名">{{detail.name}}</el-descriptions-item><el-descriptions-item label="学院">{{detail.college}}</el-descriptions-item><el-descriptions-item label="电话">{{detail.phone}}</el-descriptions-item><el-descriptions-item label="邮箱">{{detail.email}}</el-descriptions-item><el-descriptions-item label="办公地址">{{detail.officeAddress}}</el-descriptions-item><el-descriptions-item label="状态">{{statusLabel(detail.status)}}</el-descriptions-item></el-descriptions><h4>工作经历</h4><div v-for="w in detail.workExperiences" :key="w.id" class="experience"><b>{{w.organization}}</b> - {{w.position}}（{{w.startDate}} 至 {{w.endDate}}）</div><h4>教育经历</h4><div v-for="e in detail.educationExperiences" :key="e.id" class="experience"><b>{{e.school}}</b> - {{e.major}}（{{e.degree}}）</div></el-dialog>
<el-dialog v-model="unsubmittedVisible" title="未填人员" width="min(95%,850px)"><div class="unsubmitted-tools"><el-input v-model="keyword" placeholder="搜索姓名或用户名" clearable @change="loadUnsubmitted"/><el-select v-model="collegeId" placeholder="学院" clearable @change="loadUnsubmitted"><el-option v-for="c in colleges" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-button type="primary" :disabled="!remindIds.length" @click="remind">催报选中人员</el-button><el-button @click="exportUnsubmitted">导出未填名单</el-button></div><el-table :data="unsubmitted" @selection-change="rows=>remindIds=rows.map(r=>r.id)"><el-table-column type="selection" width="48"/><el-table-column prop="username" label="用户名"/><el-table-column prop="name" label="姓名"/><el-table-column prop="college" label="学院"/><el-table-column prop="phone" label="电话"/></el-table><template #footer><el-button type="warning" :disabled="!unsubmitted.length" @click="remindAll">催报全部未填人员</el-button><el-button @click="unsubmittedVisible=false">关闭</el-button></template></el-dialog></div></template>
<script setup>import{ref,computed,onMounted}from'vue';import{useRoute}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import api from'../../utils/request';const route=useRoute(),submissions=ref([]),progress=ref({}),loading=ref(false),filterStatus=ref(''),selectedIds=ref([]),detailVisible=ref(false),detail=ref({}),unsubmittedVisible=ref(false),unsubmitted=ref([]),remindIds=ref([]),keyword=ref(''),collegeId=ref(null),colleges=ref([]),isMobile=computed(()=>window.innerWidth<768);const statCards=computed(()=>[{key:'total',label:'应填人数',value:progress.value.total||0},{key:'participated',label:'已参与',value:progress.value.participated||0},{key:'unsubmitted',label:'未填人数',value:progress.value.unsubmitted||0},{key:'submitted',label:'待审核',value:progress.value.submitted||0},{key:'approved',label:'已通过',value:progress.value.approved||0},{key:'rejected',label:'已驳回',value:progress.value.rejected||0}]);onMounted(async()=>{colleges.value=(await api.get('/public/colleges')).data;await Promise.all([loadProgress(),loadSubmissions()])});async function loadProgress(){progress.value=(await api.get(`/admin/batches/${route.params.id}/progress`)).data}async function loadSubmissions(){loading.value=true;try{const params={page:0,size:500};if(filterStatus.value)params.status=filterStatus.value;const{data}=await api.get(`/admin/batches/${route.params.id}/submissions`,{params});submissions.value=data.content||[]}finally{loading.value=false}}async function openUnsubmitted(){unsubmittedVisible.value=true;await loadUnsubmitted()}async function loadUnsubmitted(){const params={};if(keyword.value)params.keyword=keyword.value;if(collegeId.value)params.collegeId=collegeId.value;unsubmitted.value=(await api.get(`/admin/batches/${route.params.id}/unsubmitted`,{params})).data}async function sendRemind(ids){const{data}=await api.post(`/admin/batches/${route.params.id}/remind`,{counselorIds:ids});ElMessage.success(`已向 ${data.count} 人发送提醒`)}async function remind(){await sendRemind(remindIds.value)}async function remindAll(){await ElMessageBox.confirm('确认向全部未填人员发送站内提醒吗？','批次催报',{type:'warning'});await sendRemind([])}async function viewDetail(row){detail.value=(await api.get('/admin/submissions/'+row.id)).data;detailVisible.value=true}async function approve(id){await api.post('/admin/submissions/approve',{ids:[id]});ElMessage.success('已通过');await Promise.all([loadSubmissions(),loadProgress()])}async function reject(id){const{value}=await ElMessageBox.prompt('驳回原因','驳回',{type:'warning'});await api.post('/admin/submissions/'+id+'/reject',{comment:value});ElMessage.success('已驳回');await Promise.all([loadSubmissions(),loadProgress()])}async function batchApprove(){await api.post('/admin/submissions/approve',{ids:selectedIds.value});ElMessage.success('批量通过成功');await Promise.all([loadSubmissions(),loadProgress()])}function statusTag(s){return({DRAFT:'info',SUBMITTED:'warning',APPROVED:'success',REJECTED:'danger'})[s]||'info'}function statusLabel(s){return({DRAFT:'草稿',SUBMITTED:'已提交',APPROVED:'已通过',REJECTED:'已驳回'})[s]||s}function download(path,name){api.get(path,{responseType:'blob'}).then(res=>{const url=URL.createObjectURL(new Blob([res.data]));const link=document.createElement('a');link.href=url;link.download=name;link.click();URL.revokeObjectURL(url)})}function exportExcel(){download('/admin/export/submissions/'+route.params.id,'填报记录.xlsx')}function exportUnsubmitted(){download('/admin/export/unsubmitted/'+route.params.id,'未填名单.xlsx')}</script>
<style scoped>.stats{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin:18px 0}.stat{background:#fff;border:1px solid #ebeef5;padding:15px;text-align:center}.stat span{display:block;color:#909399;font-size:13px}.stat strong{font-size:25px;margin-top:5px;display:block}.stat.clickable{cursor:pointer;border-color:#409eff}.college-card{margin:18px 0}.toolbar,.unsubmitted-tools{display:flex;gap:10px;margin-bottom:14px}.experience{background:#f5f7fa;padding:9px;margin:7px 0}@media(max-width:800px){.stats{grid-template-columns:repeat(2,1fr)}.toolbar,.unsubmitted-tools{flex-wrap:wrap}.unsubmitted-tools>*{flex:1;min-width:140px}}</style>
